import{_ as o,o as e,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Teses Centrais do Anti-Predacionismo","description":"","frontmatter":{},"headers":[],"relativePath":"pt/04-反掠夺主义核心论纲.md","filePath":"pt/04-反掠夺主义核心论纲.md"}'),s={name:"pt/04-反掠夺主义核心论纲.md"};function t(d,a,n,c,m,l){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="teses-centrais-do-anti-predacionismo" tabindex="-1">Teses Centrais do Anti-Predacionismo <a class="header-anchor" href="#teses-centrais-do-anti-predacionismo" aria-label="Permalink to &quot;Teses Centrais do Anti-Predacionismo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>04</td></tr><tr><td>Módulo</td><td>Princípios Gerais e Configuração Central</td></tr><tr><td>Palavras-chave</td><td>Anti-Predacionismo, Crítica da Predação, Alternativa Simbiótica, Limite Ético, Revolução do Sistema</td></tr></tbody></table><h2 id="i-definicao-e-manifestacao-do-predacionismo" tabindex="-1">I. Definição e Manifestação do Predacionismo <a class="header-anchor" href="#i-definicao-e-manifestacao-do-predacionismo" aria-label="Permalink to &quot;I. Definição e Manifestação do Predacionismo&quot;">​</a></h2><p>O predacionismo refere-se a uma visão cósmica e a um sistema de cultivo que tem como meio central a apropriação gratuita, a devoração ou a exploração da origem, energia, sorte e recursos de outros seres ou planos, com o objetivo de alcançar a evolução própria ou do próprio grupo. O predacionismo não é um método de cultivo específico, mas uma posição fundamental que permeia a filosofia de cultivo, as instituições sociais e as relações civilizacionais.</p><p>Na história de Heng Yuan Zhou, o predacionismo manifestou-se nas seguintes formas principais:</p><table tabindex="0"><thead><tr><th>Forma</th><th>Manifestação</th><th>Dano</th></tr></thead><tbody><tr><td>Predação de Energia</td><td>Devora diretamente a energia de cultivo ou a origem de outros seres</td><td>Causa a morte ou a ruína total do cultivo do predado, o ciclo de energia cósmica é interrompido</td></tr><tr><td>Predação de Sorte</td><td>Rouba a sorte de outros indivíduos ou raças através de artes secretas</td><td>Causa o colapso do destino do predado, o declínio da raça</td></tr><tr><td>Monopólio de Métodos</td><td>Algumas seitas monopolizam os métodos de cultivo, trocando a autorização por lealdade e recursos</td><td>Causa a estratificação rígida, os seres das camadas inferiores perdem o caminho evolutivo</td></tr><tr><td>Colonialismo Planar</td><td>Planos superiores conquistam planos inferiores, predando seus recursos e populações</td><td>Causa danos à membrana planar, colapso ecológico do plano</td></tr><tr><td>Escravidão Espiritual</td><td>Transforma outros seres em ferramentas de cultivo através do controle da alma</td><td>Priva o escravizado da sua vontade livre, viola a dignidade da vida</td></tr><tr><td>Exaustão de Recursos</td><td>Explora sem moderação os recursos de um planeta ou plano</td><td>Causa a extinção ecológica, acelera o aumento da entropia cósmica</td></tr></tbody></table><h2 id="ii-o-erro-fundamental-do-predacionismo" tabindex="-1">II. O Erro Fundamental do Predacionismo <a class="header-anchor" href="#ii-o-erro-fundamental-do-predacionismo" aria-label="Permalink to &quot;II. O Erro Fundamental do Predacionismo&quot;">​</a></h2><p>O anti-predacionismo considera que o predacionismo contém fundamentalmente três erros:</p><h3 id="_2-1-erro-da-visao-cosmica-considerar-o-cosmos-como-um-campo-de-caca-limitado" tabindex="-1">2.1 Erro da Visão Cósmica: Considerar o cosmos como um campo de caça limitado <a class="header-anchor" href="#_2-1-erro-da-visao-cosmica-considerar-o-cosmos-como-um-campo-de-caca-limitado" aria-label="Permalink to &quot;2.1 Erro da Visão Cósmica: Considerar o cosmos como um campo de caça limitado&quot;">​</a></h3><p>A visão cósmica do predacionismo considera o cosmos como um campo de caça com recursos limitados, acreditando que a evolução é necessariamente um jogo de soma zero e que o avanço dos fortes deve custar a vida dos fracos. Esta visão cósmica negligencia a &quot;evolucionabilidade&quot; do próprio cosmos — o cosmos não é um recipiente estático de recursos, mas um ser vivo que pode alcançar a ascensão dimensional global através de uma rede simbiótica ordenada. Quando os predadores devoram os fracos, eles não consomem apenas a energia dos fracos, mas também o potencial evolutivo de todo o cosmos.</p><h3 id="_2-2-erro-etico-sobrepor-o-direito-evolutivo-dos-fortes-ao-direito-a-vida-dos-fracos" tabindex="-1">2.2 Erro Ético: Sobrepor o direito evolutivo dos fortes ao direito à vida dos fracos <a class="header-anchor" href="#_2-2-erro-etico-sobrepor-o-direito-evolutivo-dos-fortes-ao-direito-a-vida-dos-fracos" aria-label="Permalink to &quot;2.2 Erro Ético: Sobrepor o direito evolutivo dos fortes ao direito à vida dos fracos&quot;">​</a></h3><p>O predacionismo aceita a &quot;lei do mais forte&quot; como lei natural, acreditando que os fortes têm o direito e até o dever de devorar os fracos. Esta visão ética confunde a seleção natural com a escolha moral. Na natureza, a lei do mais forte é uma lei ecológica inconsciente; mas numa civilização de cultivo consciente, os fortes têm a capacidade de escolher e, portanto, devem assumir a responsabilidade da sua escolha. A predação usando a &quot;lei celestial&quot; como desculpa é, em essência, os fortes a vestirem a sua própria ganância como lei cósmica.</p><h3 id="_2-3-erro-de-eficiencia-acreditar-que-a-predacao-e-o-caminho-evolutivo-mais-rapido" tabindex="-1">2.3 Erro de Eficiência: Acreditar que a predação é o caminho evolutivo mais rápido <a class="header-anchor" href="#_2-3-erro-de-eficiencia-acreditar-que-a-predacao-e-o-caminho-evolutivo-mais-rapido" aria-label="Permalink to &quot;2.3 Erro de Eficiência: Acreditar que a predação é o caminho evolutivo mais rápido&quot;">​</a></h3><p>O predacionismo afirma que a predação é o caminho evolutivo mais rápido e eficiente. No entanto, a longo prazo, a evolução predatória tem um grave &quot;teto de eficiência&quot;: primeiro, a energia obtida pela predação carrega frequentemente vestígios da vontade do dono original, exigindo um grande esforço para refinar e purificar; segundo, o comportamento predatório provoca a resistência dos predados e dos seus grupos associados, aumentando os custos externos do cultivo; terceiro, a dependência a longo prazo da predação leva à degeneração da própria capacidade evolutiva do cultivador, que entra em estagnação uma vez perdido o objeto de predação; quarto, os cultivadores predatórios enfrentam frequentemente o gargalo da &quot;origem impura&quot; ao atingirem os níveis mais elevados, sendo incapazes de tocar verdadeiramente a origem cósmica.</p><h2 id="iii-as-proposicoes-centrais-do-anti-predacionismo" tabindex="-1">III. As Proposições Centrais do Anti-Predacionismo <a class="header-anchor" href="#iii-as-proposicoes-centrais-do-anti-predacionismo" aria-label="Permalink to &quot;III. As Proposições Centrais do Anti-Predacionismo&quot;">​</a></h2><p>O anti-predacionismo não nega simplesmente toda a competição e diferença, mas propõe as seguintes proposições centrais:</p><ol><li><strong>A evolução pode não ser de soma zero</strong>: Através do ciclo simbiótico e da rede de pontos de âncora, a evolução das Dez Mil Raças pode gerar efeitos sinérgicos, alcançando uma eficiência evolutiva global superior à soma das partes.</li><li><strong>A competição deve ser criativa e não destrutiva</strong>: O anti-predacionismo não se opõe à competição saudável, mas a forma de competição deve ser o aumento da própria capacidade criativa, e não a capacidade predatória de eliminar o adversário.</li><li><strong>A responsabilidade dos fortes é maior que os seus direitos</strong>: Quanto mais elevado o nível do cultivador, maior é a sua responsabilidade para com a rede simbiótica, e não maior o seu direito de predação. Os cultivadores avançados têm a obrigação de orientar os cultivadores iniciantes, manter a estabilidade dos pontos de âncora e proteger a segurança da civilização.</li><li><strong>Os recursos devem ser aumentados através da criação e não distribuídos através da predação</strong>: A ideia central da civilização simbiótica é aumentar o bolo, e não dividi-lo; através do progresso tecnológico e da aplicação das leis, criar continuamente novos recursos de cultivo.</li><li><strong>O anti-predacionismo não é igualitarismo</strong>: O que o anti-predacionismo opõe é a predação sem esforço, e não a diferença de mais trabalho, mais recompensa. A civilização simbiótica reconhece as diferenças nos resultados evolutivos, mas insiste em que as diferenças devem originar-se do próprio esforço e contribuição.</li></ol><h2 id="iv-garantia-institucional-do-anti-predacionismo" tabindex="-1">IV. Garantia Institucional do Anti-Predacionismo <a class="header-anchor" href="#iv-garantia-institucional-do-anti-predacionismo" aria-label="Permalink to &quot;IV. Garantia Institucional do Anti-Predacionismo&quot;">​</a></h2><p>O anti-predacionismo não é apenas uma proposição teórica, mas tem uma série de garantias institucionais:</p><ul><li><strong>Garantia Jurídica</strong>: A constituição simbiótica e a lei anti-monopólio proíbem explicitamente o comportamento predatório, o Tribunal da Âncora tem jurisdição sobre os casos de predação</li><li><strong>Garantia Mecanística</strong>: O sistema de contrato vinculado à produção assegura que a distribuição de recursos se baseia na contribuição e não na violência, a rede de pontos de âncora monitora fluxos de energia anormais</li><li><strong>Garantia de Sistema</strong>: Os Trezentos Sistemas de Cultivo da Origem baseiam-se todos no princípio do ciclo simbiótico, não existem métodos predatórios</li><li><strong>Garantia Educacional</strong>: O sistema educacional simbiótico torna a ética anti-predatória uma disciplina obrigatória, erradicando o pensamento predatório desde a raiz</li><li><strong>Garantia de Supervisão</strong>: O Parlamento da República das Dez Mil Raças cria uma comissão anti-predatória, especializada em supervisionar e investigar o comportamento predatório</li></ul><h2 id="v-politica-para-as-forcas-predatorias-remanescentes" tabindex="-1">V. Política para as Forças Predatórias Remanescentes <a class="header-anchor" href="#v-politica-para-as-forcas-predatorias-remanescentes" aria-label="Permalink to &quot;V. Política para as Forças Predatórias Remanescentes&quot;">​</a></h2><p>Para as forças predatórias remanescentes que ainda existem no cosmos, a civilização simbiótica adota a política combinada de &quot;isolamento, transformação, sanção&quot;: para os predadores que ainda não causaram danos graves, realiza-se educação ética e transformação do sistema, orientando-os a juntar-se ao sistema simbiótico; para os predadores que recusam a transformação e continuam a prejudicar a ordem simbiótica, aplica-se o isolamento planar e a restrição do cultivo; para os predadores que causam desastres graves, aplica-se a sanção de acordo com a lei. A civilização simbiótica não defende o anti-predacionismo através da predação, e todas as sanções devem passar por um julgamento justo do Tribunal da Âncora.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O anti-predacionismo é uma das bases teóricas da Civilização Simbiótica da Âncora. Não é apenas uma crítica ao sistema predatório da velha era, mas também uma construção ativa da possibilidade da evolução simbiótica. O objetivo último do anti-predacionismo não é eliminar os fortes, mas fazer com que o poder dos fortes sirva a evolução comum das Dez Mil Raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Declaração da Civilização Simbiótica da Âncora)</li><li>03-共生文明宪章 (Constituição da Civilização Simbiótica)</li><li>19-修炼伦理与边界 (Ética e Limites do Cultivo)</li></ul>',26)])])}const v=o(s,[["render",t]]);export{p as __pageData,v as default};
